def summarize_expenses(csv_text):
    """Total the amount column per category.

    Returns {category: total} with each total rounded to 2 decimals.
    Category keys are lowercase with surrounding whitespace stripped.
    Amounts may be quoted and may use $ and thousands separators.
    An amount wrapped in parentheses is negative, accounting style.
    Rows with a missing or empty amount are skipped, as are blank lines.
    """
    import csv
    import io
    import re

    totals = {}
    reader = csv.reader(io.StringIO(csv_text))
    header = next(reader, None)  # skip header
    for row in reader:
        # skip blank lines
        if not row or all(cell.strip() == '' for cell in row):
            continue
        # need at least 3 fields (date, category, amount)
        if len(row) < 3:
            continue
        category = row[1].strip().lower()
        raw_amount = row[2].strip()
        # skip missing or empty amount
        if raw_amount == '':
            continue
        # parse amount
        negative = False
        if raw_amount.startswith('(') and raw_amount.endswith(')'):
            negative = True
            raw_amount = raw_amount[1:-1]
        # remove $ and commas
        raw_amount = raw_amount.replace('$', '').replace(',', '').strip()
        try:
            value = float(raw_amount)
        except ValueError:
            continue
        if negative:
            value = -value
        totals[category] = totals.get(category, 0) + value

    return {k: round(v, 2) for k, v in totals.items()}
